-- composition of rule kernels build_side_probe_side x partitioned_execution (duckdb), template cte_twice
WITH ka AS (SELECT DISTINCT 10::bigint AS c0, a1.c0 AS c1 FROM tl AS a1), kb AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT ARRAY['x'::text, NULL::text] AS c0, 10.0::float8 AS c1, (SELECT MIN ('-1 month'::interval) FROM t0 AS a3) AS c2 FROM t3 AS a1 WHERE (SELECT BOOL_AND (TRUE) FROM t4 AS a2) UNION ALL SELECT ARRAY['1'::text] AS c0, 0.0::float8 AS c1, '00:00:00.000001'::interval AS c2) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
